import { TriviaQuestion } from '../trivia-types'

export const SCIENCE_QUESTIONS: TriviaQuestion[] = [
  { id: 'sci-1', category: 'science', difficulty: 'easy', question: 'What is the chemical symbol for gold?', answer: 'Au', options: ['Go', 'Au', 'Ag', 'Gd'], explanation: 'Au comes from the Latin word "aurum," meaning gold. Silver\'s symbol Ag similarly comes from the Latin "argentum."' },
  { id: 'sci-2', category: 'science', difficulty: 'easy', question: 'How many planets are in our solar system?', answer: '8', options: ['7', '8', '9', '10'], explanation: 'There are 8 planets since Pluto was reclassified as a dwarf planet by the International Astronomical Union in 2006. The planets are Mercury, Venus, Earth, Mars, Jupiter, Saturn, Uranus, and Neptune.' },
  { id: 'sci-3', category: 'science', difficulty: 'easy', question: 'What is the largest organ in the human body?', answer: 'Skin', options: ['Liver', 'Skin', 'Lungs', 'Brain'], explanation: 'The skin covers about 20 square feet in adults and weighs about 8 pounds. The liver is the largest internal organ.' },
  { id: 'sci-4', category: 'science', difficulty: 'easy', question: 'What gas do plants absorb from the atmosphere during photosynthesis?', answer: 'Carbon dioxide', options: ['Oxygen', 'Nitrogen', 'Carbon dioxide', 'Hydrogen'], explanation: 'Plants take in carbon dioxide and water, using sunlight to convert them into glucose and oxygen. This process is the foundation of most food chains on Earth.' },
  { id: 'sci-5', category: 'science', difficulty: 'easy', question: 'What planet is known as the Red Planet?', answer: 'Mars', options: ['Venus', 'Jupiter', 'Mars', 'Mercury'], explanation: 'Mars appears red due to iron oxide (rust) on its surface. It has two small moons named Phobos and Deimos.' },
  { id: 'sci-6', category: 'science', difficulty: 'easy', question: 'What is the hardest natural substance on Earth?', answer: 'Diamond', options: ['Quartz', 'Topaz', 'Diamond', 'Corundum'], explanation: 'Diamond scores 10 on the Mohs hardness scale, the highest possible rating. Diamonds are made of carbon atoms arranged in a crystal lattice structure.' },
  { id: 'sci-7', category: 'science', difficulty: 'easy', question: 'How many bones are in the adult human body?', answer: '206', options: ['186', '206', '256', '306'], explanation: 'Babies are born with about 270 bones, but many fuse together as they grow. The smallest bone is the stapes in the middle ear.' },
  { id: 'sci-8', category: 'science', difficulty: 'easy', question: 'What is the chemical formula for water?', answer: 'H2O', options: ['HO2', 'H2O', 'H2O2', 'OH'], explanation: 'Water is made of two hydrogen atoms and one oxygen atom. H2O2 is hydrogen peroxide, a completely different compound.' },
  { id: 'sci-9', category: 'science', difficulty: 'easy', question: 'What force keeps us on the ground?', answer: 'Gravity', options: ['Magnetism', 'Friction', 'Gravity', 'Inertia'], explanation: 'Gravity is the force of attraction between objects with mass. Isaac Newton famously described its laws in 1687, and Einstein later refined the concept with general relativity in 1915.' },
  { id: 'sci-10', category: 'science', difficulty: 'easy', question: 'What is the closest star to Earth?', answer: 'The Sun', options: ['Proxima Centauri', 'The Sun', 'Alpha Centauri A', 'Sirius'], explanation: 'The Sun is about 93 million miles from Earth. The next closest star, Proxima Centauri, is about 4.24 light-years away.' },
  { id: 'sci-11', category: 'science', difficulty: 'easy', question: 'What type of animal is a dolphin?', answer: 'Mammal', options: ['Fish', 'Mammal', 'Reptile', 'Amphibian'], explanation: 'Dolphins are warm-blooded, breathe air, give live birth, and nurse their young with milk. They belong to the order Cetacea, which also includes whales and porpoises.' },
  { id: 'sci-12', category: 'science', difficulty: 'easy', question: 'What element does "O" represent on the periodic table?', answer: 'Oxygen', options: ['Osmium', 'Oxygen', 'Oganesson', 'Gold'], explanation: 'Oxygen makes up about 21% of Earth\'s atmosphere. It was discovered independently by Carl Wilhelm Scheele and Joseph Priestley in the 1770s.' },
  { id: 'sci-13', category: 'science', difficulty: 'easy', question: 'What is the boiling point of water in Fahrenheit?', answer: '212°F', options: ['100°F', '180°F', '212°F', '200°F'], explanation: 'Water boils at 212°F (100°C) at standard atmospheric pressure. The freezing point is 32°F (0°C).' },
  { id: 'sci-14', category: 'science', difficulty: 'easy', question: 'What part of the cell contains genetic material?', answer: 'Nucleus', options: ['Mitochondria', 'Nucleus', 'Ribosome', 'Cell membrane'], explanation: 'The nucleus houses DNA organized into chromosomes. It is often called the "control center" of the cell because it directs cell activities.' },
  { id: 'sci-15', category: 'science', difficulty: 'easy', question: 'What is the largest planet in our solar system?', answer: 'Jupiter', options: ['Saturn', 'Jupiter', 'Neptune', 'Uranus'], explanation: 'Jupiter is so massive that over 1,300 Earths could fit inside it. Its Great Red Spot is a storm that has been raging for at least 350 years.' },
  { id: 'sci-16', category: 'science', difficulty: 'easy', question: 'What vitamin does the body produce when exposed to sunlight?', answer: 'Vitamin D', options: ['Vitamin A', 'Vitamin C', 'Vitamin D', 'Vitamin B12'], explanation: 'The skin synthesizes Vitamin D when exposed to UVB radiation from sunlight. Vitamin D is essential for calcium absorption and bone health.' },
  { id: 'sci-17', category: 'science', difficulty: 'easy', question: 'What is the most abundant gas in Earth\'s atmosphere?', answer: 'Nitrogen', options: ['Oxygen', 'Nitrogen', 'Carbon dioxide', 'Argon'], explanation: 'Nitrogen makes up about 78% of the atmosphere, while oxygen accounts for about 21%. The remaining 1% includes argon, carbon dioxide, and trace gases.' },
  { id: 'sci-18', category: 'science', difficulty: 'easy', question: 'What scientist is known for the theory of relativity?', answer: 'Albert Einstein', options: ['Isaac Newton', 'Albert Einstein', 'Niels Bohr', 'Max Planck'], explanation: 'Einstein published his special theory of relativity in 1905 and general relativity in 1915. He won the Nobel Prize in Physics in 1921 for the photoelectric effect, not relativity.' },
  { id: 'sci-19', category: 'science', difficulty: 'easy', question: 'What is the powerhouse of the cell?', answer: 'Mitochondria', options: ['Nucleus', 'Ribosome', 'Mitochondria', 'Golgi apparatus'], explanation: 'Mitochondria generate most of the cell\'s supply of ATP, the molecule used as energy currency. They have their own DNA, supporting the theory that they were once independent organisms.' },
  { id: 'sci-20', category: 'science', difficulty: 'easy', question: 'What blood type is known as the universal donor?', answer: 'O negative', options: ['A positive', 'AB positive', 'O negative', 'B negative'], explanation: 'O negative blood can be given to patients of any blood type because it lacks A, B, and Rh antigens. AB positive is the universal recipient.' },
  { id: 'sci-21', category: 'science', difficulty: 'easy', question: 'What is the speed of light in miles per second (approximately)?', answer: '186,000', options: ['126,000', '186,000', '246,000', '386,000'], explanation: 'Light travels at approximately 186,000 miles per second (about 300,000 km/s). It takes about 8 minutes for sunlight to reach Earth.' },
  { id: 'sci-22', category: 'science', difficulty: 'easy', question: 'What animal is the largest living land mammal?', answer: 'African elephant', options: ['White rhinoceros', 'African elephant', 'Hippopotamus', 'Giraffe'], explanation: 'African elephants can weigh up to 14,000 pounds and stand up to 13 feet tall at the shoulder. They are also the largest living land animal of any kind.' },
  { id: 'sci-23', category: 'science', difficulty: 'easy', question: 'What does DNA stand for?', answer: 'Deoxyribonucleic acid', options: ['Deoxyribonucleic acid', 'Dinitrogen acid', 'Deoxyribonitric acid', 'Dinucleotide acid'], explanation: 'DNA carries the genetic instructions for the development and functioning of all known living organisms. Its double helix structure was described by Watson and Crick in 1953.' },
  { id: 'sci-24', category: 'science', difficulty: 'easy', question: 'What is the smallest planet in our solar system?', answer: 'Mercury', options: ['Mars', 'Mercury', 'Venus', 'Pluto'], explanation: 'Mercury has a diameter of about 3,032 miles, making it the smallest planet. Pluto is smaller but was reclassified as a dwarf planet in 2006.' },
  { id: 'sci-25', category: 'science', difficulty: 'easy', question: 'How many chambers does the human heart have?', answer: '4', options: ['2', '3', '4', '5'], explanation: 'The heart has four chambers: two atria (upper) and two ventricles (lower). The right side pumps blood to the lungs, while the left side pumps it to the rest of the body.' },
  { id: 'sci-26', category: 'science', difficulty: 'easy', question: 'What is the chemical symbol for sodium?', answer: 'Na', options: ['So', 'Na', 'Sd', 'No'], explanation: 'Na comes from the Latin word "natrium." Sodium is a highly reactive alkali metal that reacts vigorously with water.' },
  { id: 'sci-27', category: 'science', difficulty: 'easy', question: 'What is the main gas found in the air we breathe out?', answer: 'Carbon dioxide', options: ['Oxygen', 'Nitrogen', 'Carbon dioxide', 'Helium'], explanation: 'While we exhale mostly nitrogen (which we don\'t use), the significant change is that we convert inhaled oxygen into carbon dioxide during cellular respiration. Exhaled air still contains about 16% oxygen.' },
  { id: 'sci-28', category: 'science', difficulty: 'easy', question: 'What scale is used to measure the magnitude of earthquakes?', answer: 'Richter scale', options: ['Beaufort scale', 'Richter scale', 'Mohs scale', 'Mercalli scale'], explanation: 'The Richter scale was developed by Charles Richter in 1935. Each whole number increase represents a tenfold increase in measured amplitude and roughly 31.6 times more energy released.' },
  { id: 'sci-29', category: 'science', difficulty: 'easy', question: 'What planet has the most moons in our solar system?', answer: 'Saturn', options: ['Jupiter', 'Saturn', 'Uranus', 'Neptune'], explanation: 'Saturn has over 140 known moons as of recent discoveries, surpassing Jupiter. Its largest moon, Titan, has a thick atmosphere and liquid methane lakes.' },
  { id: 'sci-30', category: 'science', difficulty: 'easy', question: 'What is the study of fossils called?', answer: 'Paleontology', options: ['Archaeology', 'Paleontology', 'Geology', 'Anthropology'], explanation: 'Paleontology studies prehistoric life through fossils, while archaeology studies human history through artifacts. The two fields sometimes overlap when studying early humans.' },
  { id: 'sci-31', category: 'science', difficulty: 'easy', question: 'Which scientist formulated the three laws of motion?', answer: 'Isaac Newton', options: ['Galileo Galilei', 'Isaac Newton', 'Albert Einstein', 'Johannes Kepler'], explanation: 'Newton published his three laws of motion in "Principia Mathematica" in 1687. His first law states that an object at rest stays at rest unless acted upon by an external force.' },
  { id: 'sci-32', category: 'science', difficulty: 'easy', question: 'What is the largest animal ever to have lived on Earth?', answer: 'Blue whale', options: ['African elephant', 'Blue whale', 'Argentinosaurus', 'Megalodon'], explanation: 'Blue whales can reach lengths of about 100 feet and weigh up to 200 tons, larger than any known dinosaur. Their hearts are roughly the size of a small car.' },
  { id: 'sci-33', category: 'science', difficulty: 'easy', question: 'What type of rock is formed from cooled lava or magma?', answer: 'Ignite (Igneous)', options: ['Sedimentary', 'Ignite (Igneous)', 'Metamorphic', 'Calcium'], explanation: 'Igneous rocks form when molten rock cools and solidifies. Granite and basalt are common examples, with granite forming underground and basalt forming on the surface.' },
  { id: 'sci-34', category: 'science', difficulty: 'easy', question: 'What element has the atomic number 1?', answer: 'Hydrogen', options: ['Helium', 'Hydrogen', 'Lithium', 'Carbon'], explanation: 'Hydrogen is the lightest and most abundant element in the universe, making up about 75% of all matter. It has just one proton and one electron.' },
  { id: 'sci-35', category: 'science', difficulty: 'easy', question: 'What part of the human eye controls the amount of light entering?', answer: 'Iris', options: ['Retina', 'Cornea', 'Iris', 'Lens'], explanation: 'The iris is the colored part of the eye that contracts or expands to control pupil size. In bright light the pupil constricts, and in dim light it dilates.' },
  { id: 'sci-36', category: 'science', difficulty: 'medium', question: 'What is the half-life of Carbon-14, approximately?', answer: '5,730 years', options: ['1,200 years', '5,730 years', '12,500 years', '25,000 years'], explanation: 'Carbon-14 dating is used to determine the age of organic materials up to about 50,000 years old. It was developed by Willard Libby in 1949, earning him the 1960 Nobel Prize in Chemistry.' },
  { id: 'sci-37', category: 'science', difficulty: 'medium', question: 'What is the most abundant element in the Earth\'s crust?', answer: 'Oxygen', options: ['Silicon', 'Oxygen', 'Iron', 'Aluminum'], explanation: 'Oxygen makes up about 46% of the Earth\'s crust by mass, mostly bound in silicate and oxide minerals. Silicon is second at about 28%.' },
  { id: 'sci-38', category: 'science', difficulty: 'medium', question: 'Who discovered penicillin?', answer: 'Alexander Fleming', options: ['Louis Pasteur', 'Alexander Fleming', 'Joseph Lister', 'Robert Koch'], explanation: 'Fleming discovered penicillin in 1928 when he noticed mold killing bacteria in a petri dish. He shared the 1945 Nobel Prize in Medicine with Howard Florey and Ernst Boris Chain, who developed it for mass production.' },
  { id: 'sci-39', category: 'science', difficulty: 'medium', question: 'What is the largest bone in the human body?', answer: 'Femur', options: ['Tibia', 'Femur', 'Humerus', 'Pelvis'], explanation: 'The femur (thigh bone) is the longest, heaviest, and strongest bone in the human body. It can support up to 30 times the weight of an adult.' },
  { id: 'sci-40', category: 'science', difficulty: 'medium', question: 'What phenomenon causes the Northern Lights?', answer: 'Charged particles from the Sun interacting with the atmosphere', options: ['Reflection of sunlight off ice crystals', 'Charged particles from the Sun interacting with the atmosphere', 'Volcanic gas emissions in the upper atmosphere', 'Moonlight refracted through atmospheric layers'], explanation: 'Solar wind carries charged particles that interact with gases in Earth\'s magnetosphere, producing aurora borealis. Different gases produce different colors: oxygen creates green and red, nitrogen creates blue and purple.' },
  { id: 'sci-41', category: 'science', difficulty: 'medium', question: 'What is the Mohs hardness of talc?', answer: '1', options: ['1', '2', '3', '0.5'], explanation: 'Talc is the softest mineral on the Mohs scale at 1, while diamond is the hardest at 10. Talc is so soft it can be scratched with a fingernail.' },
  { id: 'sci-42', category: 'science', difficulty: 'medium', question: 'What scientist is credited with developing the first successful polio vaccine?', answer: 'Jonas Salk', options: ['Jonas Salk', 'Albert Sabin', 'Louis Pasteur', 'Edward Jenner'], explanation: 'Jonas Salk developed the inactivated polio vaccine in 1955. Albert Sabin later developed an oral polio vaccine. Salk famously refused to patent his vaccine, saying "Could you patent the sun?"' },
  { id: 'sci-43', category: 'science', difficulty: 'medium', question: 'What is the second most abundant element in the universe?', answer: 'Helium', options: ['Oxygen', 'Carbon', 'Helium', 'Nitrogen'], explanation: 'Helium makes up about 24% of the observable universe\'s mass, second only to hydrogen at about 74%. Helium was first discovered in the Sun\'s spectrum before it was found on Earth.' },
  { id: 'sci-44', category: 'science', difficulty: 'medium', question: 'What is the process by which cells divide to produce two identical daughter cells?', answer: 'Mitosis', options: ['Meiosis', 'Mitosis', 'Binary fission', 'Cytokinesis'], explanation: 'Mitosis produces two genetically identical cells and is used for growth and repair. Meiosis, in contrast, produces four genetically diverse cells with half the chromosomes, used for sexual reproduction.' },
  { id: 'sci-45', category: 'science', difficulty: 'medium', question: 'What planet rotates on its side with an axial tilt of about 98 degrees?', answer: 'Uranus', options: ['Neptune', 'Uranus', 'Saturn', 'Venus'], explanation: 'Uranus essentially rolls around the Sun on its side, likely due to a massive collision early in its history. This extreme tilt means its poles get about 42 years of continuous sunlight followed by 42 years of darkness.' },
  { id: 'sci-46', category: 'science', difficulty: 'medium', question: 'What is the SI unit of electric current?', answer: 'Ampere', options: ['Volt', 'Ampere', 'Watt', 'Ohm'], explanation: 'The ampere (amp) measures the flow of electric charge, named after French physicist Andre-Marie Ampere. One ampere equals one coulomb of charge passing a point per second.' },
  { id: 'sci-47', category: 'science', difficulty: 'medium', question: 'What type of bond involves the sharing of electron pairs between atoms?', answer: 'Covalent bond', options: ['Ionic bond', 'Covalent bond', 'Metallic bond', 'Hydrogen bond'], explanation: 'In covalent bonds, atoms share electrons to achieve stable electron configurations. Ionic bonds involve the transfer of electrons, while metallic bonds involve a "sea" of shared electrons.' },
  { id: 'sci-48', category: 'science', difficulty: 'medium', question: 'What is the name of the supercontinent that existed about 300 million years ago?', answer: 'Pangaea', options: ['Gondwana', 'Pangaea', 'Laurasia', 'Rodinia'], explanation: 'Pangaea began breaking apart about 200 million years ago. Gondwana and Laurasia were the two major landmasses it split into, which further broke apart into today\'s continents.' },
  { id: 'sci-49', category: 'science', difficulty: 'medium', question: 'Who is known as the father of modern taxonomy?', answer: 'Carl Linnaeus', options: ['Charles Darwin', 'Carl Linnaeus', 'Gregor Mendel', 'Aristotle'], explanation: 'Carl Linnaeus established the binomial nomenclature system for naming species in 1735. His system uses two Latin names (genus and species), such as Homo sapiens for humans.' },
  { id: 'sci-50', category: 'science', difficulty: 'medium', question: 'What is the pH of pure water?', answer: '7', options: ['0', '5', '7', '14'], explanation: 'A pH of 7 is considered neutral, meaning it is neither acidic nor basic. The pH scale runs from 0 (most acidic) to 14 (most basic), and each whole number represents a tenfold change.' },
  { id: 'sci-51', category: 'science', difficulty: 'medium', question: 'What planet has the Great Red Spot?', answer: 'Jupiter', options: ['Mars', 'Jupiter', 'Saturn', 'Neptune'], explanation: 'The Great Red Spot is an anticyclonic storm on Jupiter that has been observed for over 350 years. It is so large that Earth could fit inside it multiple times.' },
  { id: 'sci-52', category: 'science', difficulty: 'medium', question: 'What scientist proposed the heliocentric model of the solar system?', answer: 'Nicolaus Copernicus', options: ['Galileo Galilei', 'Nicolaus Copernicus', 'Johannes Kepler', 'Tycho Brahe'], explanation: 'Copernicus published his heliocentric theory in 1543 in "De Revolutionibus." While Galileo later championed the theory, Copernicus was the first to formally propose a Sun-centered model in the modern era.' },
  { id: 'sci-53', category: 'science', difficulty: 'medium', question: 'What is the most common blood type in humans?', answer: 'O positive', options: ['A positive', 'O positive', 'B positive', 'AB positive'], explanation: 'About 38% of the global population has O positive blood. The rarest common blood type is AB negative, found in less than 1% of the population.' },
  { id: 'sci-54', category: 'science', difficulty: 'medium', question: 'What layer of the atmosphere do commercial airplanes typically fly in?', answer: 'Stratosphere', options: ['Troposphere', 'Stratosphere', 'Mesosphere', 'Thermosphere'], explanation: 'Commercial jets cruise at about 35,000-40,000 feet, which is in the lower stratosphere. The stratosphere is calmer than the troposphere below it, making for smoother flights.' },
  { id: 'sci-55', category: 'science', difficulty: 'medium', question: 'How many chromosomes do humans have?', answer: '46', options: ['23', '44', '46', '48'], explanation: 'Humans have 23 pairs of chromosomes for a total of 46. Egg and sperm cells each contain 23 chromosomes (one from each pair), which combine during fertilization.' },
  { id: 'sci-56', category: 'science', difficulty: 'medium', question: 'What was the first element created artificially?', answer: 'Technetium', options: ['Plutonium', 'Technetium', 'Neptunium', 'Francium'], explanation: 'Technetium was synthesized in 1937 by Carlo Perrier and Emilio Segre. Its name comes from the Greek word "technetos," meaning artificial. It is the lightest element with no stable isotopes.' },
  { id: 'sci-57', category: 'science', difficulty: 'medium', question: 'What is the largest species of shark?', answer: 'Whale shark', options: ['Great white shark', 'Whale shark', 'Basking shark', 'Megamouth shark'], explanation: 'Whale sharks can grow up to 60 feet or more and weigh up to 20 tons. Despite their enormous size, they are filter feeders that eat plankton and small fish.' },
  { id: 'sci-58', category: 'science', difficulty: 'medium', question: 'What organ produces insulin in the human body?', answer: 'Pancreas', options: ['Liver', 'Pancreas', 'Kidney', 'Gallbladder'], explanation: 'The pancreas produces insulin in specialized cells called beta cells within the islets of Langerhans. When these cells are destroyed or dysfunctional, it results in diabetes.' },
  { id: 'sci-59', category: 'science', difficulty: 'medium', question: 'What is absolute zero in Fahrenheit?', answer: '-459.67°F', options: ['-273.15°F', '-459.67°F', '-500°F', '-321°F'], explanation: 'Absolute zero is -459.67°F (-273.15°C or 0 Kelvin), the lowest theoretically possible temperature. At this temperature, all molecular motion would cease.' },
  { id: 'sci-60', category: 'science', difficulty: 'medium', question: 'Who developed the periodic table of elements?', answer: 'Dmitri Mendeleev', options: ['Antoine Lavoisier', 'Dmitri Mendeleev', 'John Dalton', 'Lothar Meyer'], explanation: 'Mendeleev published his periodic table in 1869, organizing elements by atomic weight and predicting undiscovered elements. Lothar Meyer independently developed a similar table around the same time.' },
  { id: 'sci-61', category: 'science', difficulty: 'medium', question: 'What is the name of the rover that NASA landed on Mars in February 2021?', answer: 'Perseverance', options: ['Curiosity', 'Perseverance', 'Opportunity', 'Spirit'], explanation: 'Perseverance landed in Jezero Crater and carries the Ingenuity helicopter, the first aircraft to fly on another planet. The rover is searching for signs of ancient microbial life.' },
  { id: 'sci-62', category: 'science', difficulty: 'medium', question: 'What is the term for an animal that eats both plants and meat?', answer: 'Omnivore', options: ['Herbivore', 'Carnivore', 'Omnivore', 'Insectivore'], explanation: 'Omnivores include humans, bears, pigs, and crows. The word comes from the Latin "omnis" (all) and "vorare" (to devour).' },
  { id: 'sci-63', category: 'science', difficulty: 'medium', question: 'What subatomic particle has a positive charge?', answer: 'Proton', options: ['Electron', 'Proton', 'Neutron', 'Photon'], explanation: 'Protons carry a positive charge and reside in the atom\'s nucleus alongside neutrons. The number of protons defines what element an atom is (its atomic number).' },
  { id: 'sci-64', category: 'science', difficulty: 'medium', question: 'What was the first animal to be cloned from an adult somatic cell?', answer: 'Dolly the sheep', options: ['A mouse', 'Dolly the sheep', 'A cat', 'A frog'], explanation: 'Dolly was born on July 5, 1996, at the Roslin Institute in Scotland. She was cloned from a mammary gland cell and named after Dolly Parton.' },
  { id: 'sci-65', category: 'science', difficulty: 'medium', question: 'What is the chemical symbol for potassium?', answer: 'K', options: ['P', 'Po', 'K', 'Pt'], explanation: 'K comes from the Latin "kalium" and the Arabic "al-qalyah," meaning plant ashes. Potassium is an essential mineral for human nerve and muscle function.' },
  { id: 'sci-66', category: 'science', difficulty: 'medium', question: 'What phenomenon explains why a moving ambulance siren changes pitch?', answer: 'Doppler effect', options: ['Resonance', 'Doppler effect', 'Refraction', 'Diffraction'], explanation: 'The Doppler effect causes the frequency of sound waves to increase as a source approaches and decrease as it moves away. It applies to all waves, including light, which astronomers use to determine if stars are moving toward or away from us.' },
  { id: 'sci-67', category: 'science', difficulty: 'medium', question: 'What is the largest desert in the world?', answer: 'Antarctic Desert', options: ['Sahara', 'Antarctic Desert', 'Arctic Desert', 'Gobi'], explanation: 'Antarctica is technically a desert because it receives very little precipitation (less than 2 inches per year). The Sahara is the largest hot desert, covering about 3.6 million square miles.' },
  { id: 'sci-68', category: 'science', difficulty: 'medium', question: 'What gas makes up most of the Sun\'s mass?', answer: 'Hydrogen', options: ['Helium', 'Hydrogen', 'Oxygen', 'Carbon'], explanation: 'Hydrogen makes up about 73% of the Sun\'s mass and helium about 25%. The Sun fuses about 600 million tons of hydrogen into helium every second.' },
  { id: 'sci-69', category: 'science', difficulty: 'medium', question: 'Who is credited with inventing the telephone?', answer: 'Alexander Graham Bell', options: ['Thomas Edison', 'Alexander Graham Bell', 'Nikola Tesla', 'Guglielmo Marconi'], explanation: 'Bell was awarded the patent for the telephone in 1876, though Antonio Meucci and Elisha Gray also developed similar devices. Bell\'s first words on the telephone were reportedly "Mr. Watson, come here. I want to see you."' },
  { id: 'sci-70', category: 'science', difficulty: 'medium', question: 'What is the most abundant mineral in the human body?', answer: 'Calcium', options: ['Iron', 'Calcium', 'Potassium', 'Sodium'], explanation: 'About 99% of the body\'s calcium is found in bones and teeth. Calcium is also essential for muscle contraction, nerve signaling, and blood clotting.' },
  { id: 'sci-71', category: 'science', difficulty: 'medium', question: 'What is the name of the boundary between Earth\'s crust and mantle?', answer: 'Mohorovicic discontinuity (Moho)', options: ['Gutenberg discontinuity', 'Mohorovicic discontinuity (Moho)', 'Conrad discontinuity', 'Lehmann discontinuity'], explanation: 'The Moho was discovered in 1909 by Croatian seismologist Andrija Mohorovicic. It lies about 5-10 km beneath the ocean floor and 20-90 km beneath continents.' },
  { id: 'sci-72', category: 'science', difficulty: 'medium', question: 'What famous equation relates energy and mass?', answer: 'E=mc²', options: ['F=ma', 'E=mc²', 'PV=nRT', 'V=IR'], explanation: 'Einstein\'s equation E=mc² shows that energy equals mass times the speed of light squared. This principle underlies nuclear energy, as tiny amounts of mass can release enormous amounts of energy.' },
  { id: 'sci-73', category: 'science', difficulty: 'medium', question: 'What structure in the throat prevents food from entering the windpipe?', answer: 'Epiglottis', options: ['Larynx', 'Uvula', 'Epiglottis', 'Tonsils'], explanation: 'The epiglottis is a flap of cartilage that covers the trachea during swallowing. When it malfunctions, food can enter the airway, causing choking or aspiration pneumonia.' },
  { id: 'sci-74', category: 'science', difficulty: 'medium', question: 'What is the term for the preserved remains or traces of organisms from past geological ages?', answer: 'Fossils', options: ['Artifacts', 'Fossils', 'Relics', 'Specimens'], explanation: 'Fossils form through processes like permineralization, where minerals replace organic material. The oldest known fossils are stromatolites, formed by cyanobacteria about 3.5 billion years ago.' },
  { id: 'sci-75', category: 'science', difficulty: 'medium', question: 'What planet spins backward compared to most other planets?', answer: 'Venus', options: ['Uranus', 'Venus', 'Neptune', 'Mercury'], explanation: 'Venus rotates clockwise (retrograde rotation), opposite to most planets. A day on Venus (243 Earth days) is actually longer than its year (225 Earth days).' },
  { id: 'sci-76', category: 'science', difficulty: 'medium', question: 'What type of wave is sound?', answer: 'Longitudinal wave', options: ['Transverse wave', 'Longitudinal wave', 'Electromagnetic wave', 'Surface wave'], explanation: 'Sound is a longitudinal wave where particles vibrate parallel to the direction of energy transfer. Unlike electromagnetic waves, sound requires a medium (solid, liquid, or gas) to travel through.' },
  { id: 'sci-77', category: 'science', difficulty: 'medium', question: 'What is the only metal that is liquid at room temperature?', answer: 'Mercury', options: ['Gallium', 'Mercury', 'Cesium', 'Bromine'], explanation: 'Mercury melts at -38.83°C (-37.89°F), making it liquid at standard room temperature. Bromine is the only non-metal element that is liquid at room temperature. Gallium melts just above room temperature at 29.76°C.' },
  { id: 'sci-78', category: 'science', difficulty: 'medium', question: 'Who first observed cells under a microscope and coined the term "cell"?', answer: 'Robert Hooke', options: ['Anton van Leeuwenhoek', 'Robert Hooke', 'Matthias Schleiden', 'Rudolf Virchow'], explanation: 'Robert Hooke published his observations of cork cells in "Micrographia" in 1665. He called them cells because they reminded him of the small rooms (cells) that monks lived in.' },
  { id: 'sci-79', category: 'science', difficulty: 'medium', question: 'What is the largest moon in the solar system?', answer: 'Ganymede', options: ['Titan', 'Ganymede', 'Europa', 'Callisto'], explanation: 'Ganymede is a moon of Jupiter and is larger than the planet Mercury. It is the only moon known to have its own magnetic field.' },
  { id: 'sci-80', category: 'science', difficulty: 'medium', question: 'What physicist is known for his uncertainty principle?', answer: 'Werner Heisenberg', options: ['Erwin Schrodinger', 'Werner Heisenberg', 'Niels Bohr', 'Max Born'], explanation: 'Heisenberg\'s uncertainty principle (1927) states you cannot simultaneously know both the exact position and momentum of a particle. This is a fundamental limit of nature, not a measurement limitation.' },
  { id: 'sci-81', category: 'science', difficulty: 'medium', question: 'What kind of dinosaur is the T. rex classified as?', answer: 'Theropod', options: ['Sauropod', 'Theropod', 'Ornithopod', 'Ceratopsian'], explanation: 'Theropods are bipedal, mostly carnivorous dinosaurs that include T. rex, Velociraptor, and modern birds. All living birds are classified as theropod dinosaurs.' },
  { id: 'sci-82', category: 'science', difficulty: 'medium', question: 'What is the primary function of white blood cells?', answer: 'Fighting infection', options: ['Carrying oxygen', 'Fighting infection', 'Clotting blood', 'Producing hormones'], explanation: 'White blood cells (leukocytes) are part of the immune system and defend against infections and foreign invaders. There are five main types: neutrophils, lymphocytes, monocytes, eosinophils, and basophils.' },
  { id: 'sci-83', category: 'science', difficulty: 'medium', question: 'What was the first successfully launched artificial satellite?', answer: 'Sputnik 1', options: ['Explorer 1', 'Sputnik 1', 'Vanguard 1', 'Sputnik 2'], explanation: 'The Soviet Union launched Sputnik 1 on October 4, 1957, marking the start of the Space Age. It orbited Earth for three months, transmitting radio signals that could be received worldwide.' },
  { id: 'sci-84', category: 'science', difficulty: 'medium', question: 'What vitamin deficiency causes scurvy?', answer: 'Vitamin C', options: ['Vitamin A', 'Vitamin B12', 'Vitamin C', 'Vitamin D'], explanation: 'Scurvy results from a lack of Vitamin C (ascorbic acid), causing weakness, gum disease, and skin problems. British sailors were given limes to prevent scurvy, earning them the nickname "limeys."' },
  { id: 'sci-85', category: 'science', difficulty: 'medium', question: 'What is the term for a material that does not conduct electricity?', answer: 'Insulator', options: ['Conductor', 'Insulator', 'Semiconductor', 'Superconductor'], explanation: 'Insulators like rubber, glass, and plastic resist the flow of electric current. Semiconductors fall between conductors and insulators and are the basis of modern electronics.' },
  { id: 'sci-86', category: 'science', difficulty: 'medium', question: 'What organelle is responsible for photosynthesis in plant cells?', answer: 'Chloroplast', options: ['Mitochondria', 'Chloroplast', 'Vacuole', 'Ribosome'], explanation: 'Chloroplasts contain chlorophyll, the green pigment that captures light energy. Like mitochondria, chloroplasts have their own DNA and are thought to have originated as independent organisms.' },
  { id: 'sci-87', category: 'science', difficulty: 'medium', question: 'What scientist won Nobel Prizes in both Physics and Chemistry?', answer: 'Marie Curie', options: ['Linus Pauling', 'Marie Curie', 'Albert Einstein', 'Niels Bohr'], explanation: 'Marie Curie won the Physics Nobel in 1903 (for radioactivity research) and the Chemistry Nobel in 1911 (for discovering radium and polonium). She remains the only person to win Nobels in two different sciences.' },
  { id: 'sci-88', category: 'science', difficulty: 'medium', question: 'What is the name of the effect where light bends as it passes from one medium to another?', answer: 'Refraction', options: ['Reflection', 'Refraction', 'Diffraction', 'Dispersion'], explanation: 'Refraction occurs because light changes speed when moving between media of different densities. This is why a straw appears bent when placed in a glass of water.' },
  { id: 'sci-89', category: 'science', difficulty: 'medium', question: 'What is the heaviest naturally occurring element?', answer: 'Uranium', options: ['Plutonium', 'Uranium', 'Lead', 'Radium'], explanation: 'Uranium (atomic number 92) is the heaviest element found in significant quantities in nature. Plutonium and heavier elements exist in trace amounts naturally but are primarily produced artificially.' },
  { id: 'sci-90', category: 'science', difficulty: 'medium', question: 'What structure connects muscle to bone?', answer: 'Tendon', options: ['Ligament', 'Tendon', 'Cartilage', 'Fascia'], explanation: 'Tendons connect muscles to bones, while ligaments connect bones to other bones. The Achilles tendon, connecting the calf muscle to the heel bone, is the largest and strongest tendon in the body.' },
  { id: 'sci-91', category: 'science', difficulty: 'hard', question: 'What is the Chandrasekhar limit?', answer: 'The maximum mass of a stable white dwarf star (~1.4 solar masses)', options: ['The minimum mass needed for nuclear fusion', 'The maximum mass of a stable white dwarf star (~1.4 solar masses)', 'The distance at which a black hole\'s gravity becomes inescapable', 'The temperature at which hydrogen fusion begins'], explanation: 'The Chandrasekhar limit of about 1.4 solar masses was calculated by Subrahmanyan Chandrasekhar in 1930. White dwarfs exceeding this mass will collapse further, potentially becoming neutron stars or triggering Type Ia supernovae.' },
  { id: 'sci-92', category: 'science', difficulty: 'hard', question: 'What is the name of the process by which a neutron star rapidly rotates and emits beams of radiation?', answer: 'Pulsar', options: ['Quasar', 'Pulsar', 'Magnetar', 'Blazar'], explanation: 'Pulsars are highly magnetized rotating neutron stars that emit beams of electromagnetic radiation from their poles. They were first discovered in 1967 by Jocelyn Bell Burnell and initially dubbed "LGM" (Little Green Men) because their regular signals seemed artificial.' },
  { id: 'sci-93', category: 'science', difficulty: 'hard', question: 'What physicist proposed the exclusion principle stating that no two fermions can occupy the same quantum state?', answer: 'Wolfgang Pauli', options: ['Werner Heisenberg', 'Wolfgang Pauli', 'Paul Dirac', 'Enrico Fermi'], explanation: 'The Pauli exclusion principle (1925) explains the structure of the periodic table and why matter has volume. It earned Pauli the 1945 Nobel Prize in Physics.' },
  { id: 'sci-94', category: 'science', difficulty: 'hard', question: 'What is the approximate age of the Earth?', answer: '4.54 billion years', options: ['3.2 billion years', '4.54 billion years', '5.8 billion years', '6.4 billion years'], explanation: 'This age is determined primarily through radiometric dating of meteorites and the oldest known Earth rocks. The solar system itself formed about 4.6 billion years ago from a collapsing molecular cloud.' },
  { id: 'sci-95', category: 'science', difficulty: 'hard', question: 'What particle was theorized by Peter Higgs and discovered at CERN in 2012?', answer: 'Higgs boson', options: ['Graviton', 'Higgs boson', 'Tachyon', 'W boson'], explanation: 'The Higgs boson is associated with the Higgs field, which gives particles their mass. Peter Higgs and Francois Englert shared the 2013 Nobel Prize in Physics for theorizing its existence.' },
  { id: 'sci-96', category: 'science', difficulty: 'hard', question: 'What is the name of the boundary around a black hole beyond which nothing can escape?', answer: 'Event horizon', options: ['Schwarzschild radius', 'Event horizon', 'Singularity', 'Photon sphere'], explanation: 'The event horizon is the boundary at the Schwarzschild radius where escape velocity equals the speed of light. The Schwarzschild radius defines the size of the event horizon, while the singularity is the point of infinite density at the center.' },
  { id: 'sci-97', category: 'science', difficulty: 'hard', question: 'What enzyme is responsible for unwinding the DNA double helix during replication?', answer: 'Helicase', options: ['DNA polymerase', 'Helicase', 'Ligase', 'Topoisomerase'], explanation: 'Helicase breaks the hydrogen bonds between base pairs to separate the two DNA strands. DNA polymerase then reads each strand and synthesizes a complementary copy.' },
  { id: 'sci-98', category: 'science', difficulty: 'hard', question: 'What is the most abundant protein in the human body?', answer: 'Collagen', options: ['Hemoglobin', 'Collagen', 'Keratin', 'Actin'], explanation: 'Collagen makes up about 25-35% of the body\'s total protein content. It provides structural support in skin, bones, tendons, and connective tissue, and its production decreases with age.' },
  { id: 'sci-99', category: 'science', difficulty: 'hard', question: 'What is the name of the theoretical radiation emitted by black holes?', answer: 'Hawking radiation', options: ['Cherenkov radiation', 'Hawking radiation', 'Bremsstrahlung radiation', 'Synchrotron radiation'], explanation: 'Stephen Hawking theorized in 1974 that black holes emit thermal radiation due to quantum effects near the event horizon. Over extremely long timescales, this would cause black holes to slowly evaporate.' },
  { id: 'sci-100', category: 'science', difficulty: 'hard', question: 'What element has the highest melting point?', answer: 'Tungsten', options: ['Carbon', 'Tungsten', 'Rhenium', 'Osmium'], explanation: 'Tungsten melts at 3,422°C (6,192°F), the highest of any element. This property makes it ideal for light bulb filaments and high-temperature applications. Carbon sublimes rather than truly melting at standard pressure.' },
  { id: 'sci-101', category: 'science', difficulty: 'hard', question: 'What is the smallest bone in the human body?', answer: 'Stapes', options: ['Incus', 'Stapes', 'Malleus', 'Hyoid'], explanation: 'The stapes (stirrup bone) is in the middle ear and measures about 3mm. It is one of three ossicles (malleus, incus, stapes) that transmit sound vibrations from the eardrum to the inner ear.' },
  { id: 'sci-102', category: 'science', difficulty: 'hard', question: 'What law states that the total entropy of an isolated system can never decrease?', answer: 'Second law of thermodynamics', options: ['First law of thermodynamics', 'Second law of thermodynamics', 'Third law of thermodynamics', 'Zeroth law of thermodynamics'], explanation: 'The second law of thermodynamics establishes the concept of entropy, the tendency of systems toward disorder. It explains why heat flows from hot to cold, and why perpetual motion machines are impossible.' },
  { id: 'sci-103', category: 'science', difficulty: 'hard', question: 'What was the first human organ to be successfully transplanted?', answer: 'Kidney', options: ['Heart', 'Kidney', 'Liver', 'Cornea'], explanation: 'The first successful organ transplant was a kidney transplant performed by Dr. Joseph Murray in 1954 between identical twins. Murray received the Nobel Prize in Medicine in 1990 for this achievement.' },
  { id: 'sci-104', category: 'science', difficulty: 'hard', question: 'What is the Roche limit?', answer: 'The minimum distance a satellite can orbit without being torn apart by tidal forces', options: ['The maximum distance a moon can orbit a planet', 'The minimum distance a satellite can orbit without being torn apart by tidal forces', 'The boundary of a star\'s gravitational influence', 'The distance at which solar radiation pressure equals gravity'], explanation: 'The Roche limit was first calculated by French astronomer Edouard Roche in 1848. Planetary rings, like Saturn\'s, exist within the Roche limit where moons would be torn apart by tidal forces.' },
  { id: 'sci-105', category: 'science', difficulty: 'hard', question: 'What Nobel Prize-winning technique allows scientists to edit DNA sequences precisely?', answer: 'CRISPR-Cas9', options: ['PCR', 'CRISPR-Cas9', 'Gel electrophoresis', 'Gene therapy'], explanation: 'CRISPR-Cas9 was developed by Jennifer Doudna and Emmanuelle Charpentier, who shared the 2020 Nobel Prize in Chemistry. It works like molecular scissors, cutting DNA at specific locations to add, remove, or alter genetic material.' },
  { id: 'sci-106', category: 'science', difficulty: 'hard', question: 'What is the densest naturally occurring element?', answer: 'Osmium', options: ['Iridium', 'Osmium', 'Platinum', 'Lead'], explanation: 'Osmium has a density of about 22.59 g/cm³, slightly denser than iridium. It is a hard, brittle, bluish-white transition metal in the platinum group.' },
  { id: 'sci-107', category: 'science', difficulty: 'hard', question: 'What is the name of the first antibiotic discovered?', answer: 'Penicillin', options: ['Streptomycin', 'Penicillin', 'Tetracycline', 'Sulfonamide'], explanation: 'Alexander Fleming discovered penicillin in 1928 from the mold Penicillium notatum. While sulfonamides were used earlier as antibacterial agents, penicillin is considered the first true antibiotic derived from a living organism.' },
  { id: 'sci-108', category: 'science', difficulty: 'hard', question: 'What is the most common isotope of hydrogen?', answer: 'Protium', options: ['Protium', 'Deuterium', 'Tritium', 'Hydrogen-4'], explanation: 'Protium has one proton and no neutrons, making up about 99.98% of naturally occurring hydrogen. Deuterium has one neutron and tritium has two, with tritium being radioactive.' },
  { id: 'sci-109', category: 'science', difficulty: 'hard', question: 'What is the name of the closest known black hole to Earth?', answer: 'Gaia BH1', options: ['Cygnus X-1', 'Gaia BH1', 'Sagittarius A*', 'V616 Monocerotis'], explanation: 'Gaia BH1, discovered in 2022, is about 1,560 light-years from Earth in the constellation Ophiuchus. It is a dormant black hole about 10 times the mass of the Sun, orbited by a Sun-like star.' },
  { id: 'sci-110', category: 'science', difficulty: 'hard', question: 'What part of the brain is primarily responsible for balance and coordination?', answer: 'Cerebellum', options: ['Cerebrum', 'Cerebellum', 'Brain stem', 'Hippocampus'], explanation: 'The cerebellum contains about 50% of all neurons in the brain despite being only about 10% of its volume. Damage to the cerebellum results in problems with balance, coordination, and fine motor skills.' },
  { id: 'sci-111', category: 'science', difficulty: 'hard', question: 'What is the term for the minimum energy required to start a chemical reaction?', answer: 'Activation energy', options: ['Kinetic energy', 'Activation energy', 'Potential energy', 'Ionization energy'], explanation: 'Activation energy is the energy barrier that reactants must overcome to form products. Catalysts work by lowering the activation energy, allowing reactions to proceed faster without being consumed.' },
  { id: 'sci-112', category: 'science', difficulty: 'hard', question: 'Who proposed the theory of continental drift in 1912?', answer: 'Alfred Wegener', options: ['Charles Lyell', 'Alfred Wegener', 'James Hutton', 'Arthur Holmes'], explanation: 'Wegener proposed that continents were once joined as Pangaea and drifted apart, but his theory was rejected because he could not explain the mechanism. Plate tectonics, confirmed in the 1960s, provided the explanation.' },
  { id: 'sci-113', category: 'science', difficulty: 'hard', question: 'What is the only letter that does not appear in any element name on the periodic table?', answer: 'J', options: ['J', 'Q', 'X', 'Z'], explanation: 'The letter J does not appear in any of the 118 element names. Q appears in no currently recognized element names either, but J is the classic trivia answer as it has never appeared in any IUPAC-approved element name.' },
  { id: 'sci-114', category: 'science', difficulty: 'hard', question: 'What is the largest known structure in the universe?', answer: 'Hercules-Corona Borealis Great Wall', options: ['Sloan Great Wall', 'Hercules-Corona Borealis Great Wall', 'Laniakea Supercluster', 'Bootes Void'], explanation: 'The Hercules-Corona Borealis Great Wall is a massive galactic filament about 10 billion light-years across, discovered in 2013. It is so large that light would take about 10 billion years to travel across it.' },
  { id: 'sci-115', category: 'science', difficulty: 'hard', question: 'What type of rock makes up most of the ocean floor?', answer: 'Basalt', options: ['Granite', 'Basalt', 'Limestone', 'Sandstone'], explanation: 'Oceanic crust is primarily composed of basalt, a dark, dense igneous rock. Continental crust is primarily granite, which is lighter and less dense, explaining why continents float higher on the mantle.' },
  { id: 'sci-116', category: 'science', difficulty: 'hard', question: 'What was the name of the space shuttle that tragically broke apart 73 seconds after launch in 1986?', answer: 'Challenger', options: ['Columbia', 'Challenger', 'Discovery', 'Endeavour'], explanation: 'The Challenger disaster on January 28, 1986, killed all seven crew members, including teacher Christa McAuliffe. The cause was a failed O-ring seal in the right solid rocket booster, worsened by cold launch-day temperatures.' },
  { id: 'sci-117', category: 'science', difficulty: 'hard', question: 'What is the term for the point in a planet\'s orbit where it is closest to the Sun?', answer: 'Perihelion', options: ['Aphelion', 'Perihelion', 'Perigee', 'Apogee'], explanation: 'Perihelion comes from the Greek "peri" (near) and "helios" (sun). Earth reaches perihelion around January 3rd each year, about 91.4 million miles from the Sun. Perigee and apogee refer to orbits around Earth.' },
  { id: 'sci-118', category: 'science', difficulty: 'hard', question: 'What scientist developed the first successful smallpox vaccine?', answer: 'Edward Jenner', options: ['Louis Pasteur', 'Edward Jenner', 'Robert Koch', 'Jonas Salk'], explanation: 'Jenner developed the smallpox vaccine in 1796 using cowpox material, making it the world\'s first vaccine. Smallpox was declared eradicated by the WHO in 1980, the only human disease to be completely eliminated.' },
  { id: 'sci-119', category: 'science', difficulty: 'hard', question: 'What principle states that a fluid\'s pressure decreases as its speed increases?', answer: 'Bernoulli\'s principle', options: ['Pascal\'s principle', 'Bernoulli\'s principle', 'Archimedes\' principle', 'Venturi effect'], explanation: 'Bernoulli\'s principle, published in 1738, helps explain how airplane wings generate lift. Faster-moving air over the curved top of the wing creates lower pressure than the slower air below it.' },
  { id: 'sci-120', category: 'science', difficulty: 'hard', question: 'What is the term for an organism that produces its own food through photosynthesis or chemosynthesis?', answer: 'Autotroph', options: ['Heterotroph', 'Autotroph', 'Saprotroph', 'Chemotroph'], explanation: 'Autotrophs form the base of food chains as primary producers. Plants, algae, and some bacteria are autotrophs. Heterotrophs, by contrast, must consume other organisms for energy.' },
  { id: 'sci-121', category: 'science', difficulty: 'hard', question: 'What is the approximate diameter of the observable universe?', answer: '93 billion light-years', options: ['13.8 billion light-years', '46 billion light-years', '93 billion light-years', '200 billion light-years'], explanation: 'Although the universe is about 13.8 billion years old, the expansion of space means the observable universe has a diameter of about 93 billion light-years. The edge of the observable universe is called the cosmic light horizon.' },
  { id: 'sci-122', category: 'science', difficulty: 'hard', question: 'What mineral is the primary component of quartz?', answer: 'Silicon dioxide', options: ['Calcium carbonate', 'Silicon dioxide', 'Aluminum oxide', 'Iron oxide'], explanation: 'Quartz is composed of silicon dioxide (SiO2) and is the second most abundant mineral in Earth\'s continental crust after feldspar. It is extremely hard (7 on the Mohs scale) and comes in many varieties including amethyst and citrine.' },
  { id: 'sci-123', category: 'science', difficulty: 'hard', question: 'What Nobel Prize-winning physicist is known for his diagrams representing particle interactions?', answer: 'Richard Feynman', options: ['Murray Gell-Mann', 'Richard Feynman', 'Julian Schwinger', 'Sin-Itiro Tomonaga'], explanation: 'Feynman diagrams provide a visual way to represent the behavior of subatomic particles. Feynman shared the 1965 Nobel Prize in Physics with Schwinger and Tomonaga for their work on quantum electrodynamics.' },
  { id: 'sci-124', category: 'science', difficulty: 'hard', question: 'What is the deepest point in the ocean?', answer: 'Challenger Deep', options: ['Mariana Trench', 'Challenger Deep', 'Tonga Trench', 'Puerto Rico Trench'], explanation: 'Challenger Deep, located in the Mariana Trench, reaches about 36,000 feet (nearly 7 miles) below sea level. Jacques Piccard and Don Walsh first reached the bottom in the bathyscaphe Trieste in 1960.' },
  { id: 'sci-125', category: 'science', difficulty: 'hard', question: 'What is the term for the theoretical temperature at which a substance has zero entropy?', answer: 'Absolute zero', options: ['Absolute zero', 'Curie temperature', 'Critical temperature', 'Debye temperature'], explanation: 'Absolute zero (0 Kelvin, -273.15°C) is defined by the third law of thermodynamics. It can never actually be reached, but scientists have cooled materials to within billionths of a degree above it.' },
]
